import{_ as e,o as t,c as a,ac as p}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"第十三届中央委员会第二次全体会议公报","description":"","frontmatter":{"prev":{"text":"赵紫阳在党的十三届二中全会上的报告","link":"./赵紫阳在党的十三届二中全会上的报告"},"next":false},"headers":[],"relativePath":"13/2/中国共产党第十三届中央委员会第二次全体会议公报.md","filePath":"13/2/中国共产党第十三届中央委员会第二次全体会议公报.md"}'),r={name:"13/2/中国共产党第十三届中央委员会第二次全体会议公报.md"};function o(n,_,s,c,i,l){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="第十三届中央委员会第二次全体会议公报" tabindex="-1">第十三届中央委员会第二次全体会议公报 <a class="header-anchor" href="#第十三届中央委员会第二次全体会议公报" aria-label="Permalink to &quot;第十三届中央委员会第二次全体会议公报&quot;">​</a></h1><p><em>（1988年3月19日通过）</em></p><p>  中国共产党第十三届中央委员会第二次全体会议，于1988年3月15日至19日在北京举行。</p><p>  出席这次全会的有，中央委员171人，中央候补委员107人。中央顾问委员会委员、中央纪律检查委员会委员和有关负责同志列席了会议。</p><p>  中央政治局常委赵紫阳、李鹏、乔石、胡启立、姚依林同志主持了这次会议。</p><p>  全会审议通过了中共中央总书记赵紫阳同志代表中央政治局在中国共产党第十三届中央委员会第二次全体会议作的工作报告。全会一致认为，中央政治局以改革总揽全局，在组织实施十三大决议，落实经济发展战略，推进经济体制改革和政治体制改革，加强党的建设等方面进行了卓有成效的工作。</p><p>  全会审议通过了中央政治局提出，并经党内外广泛协商，拟向七届全国人大推荐的国家机构领导人员人选名单和拟向七届全国政协推荐的全国政协领导人员人选名单。全会决定，将上述两个名单分别向七届全国人大一次会议主席团和七届全国政协一次会议主席团推荐。</p><p>  全会期间，与会同志在民主、团结和生动活泼的气氛中，就上述议题进行了充分认真的讨论。</p><p>  全会号召，全党同志要继续贯彻十三大确定的党的基本路线，加强党的自身建设，紧密团结全国各族人民，进一步解放思想，进一步深化和加快改革，扩大对外开放，持续稳定地发展国民经济，为建设富强、民主、文明的社会主义现代化国家，进行坚韧不拔的努力！</p>',9)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
